# Live row
for m in MACHINES:
    df  = st.session_state.mdata[m]
    md  = int(df['Day'].max())
    nr  = pd.DataFrame({'Day':[md+1],
                        'Vibration':[np.random.uniform(2,10.8)],
                        'Temperature':[np.random.uniform(45,94)],
                        'Fuel':[np.random.uniform(80,520)],
                        'Shift':[np.random.choice(['Morning','Evening','Night'])]})
    nr['CO2']          = nr['Fuel']*2.68*(1+nr['Vibration']/12)
    nr['Failure_Prob'] = np.clip((nr['Vibration']-4)/5.5+(nr['Temperature']-60)/32,0,0.96)
    combined = pd.concat([df,nr],ignore_index=True).tail(150).reset_index(drop=True)
    combined['Predicted_Risk'] = st.session_state.models[m].predict_proba(
        combined[['Vibration','Temperature','Fuel']])[:,1]
    st.session_state.mdata[m] = combined

# Email
def send_email(risk_pct, day, machine, vib, temp, to):
    try:
        sndr = st.secrets.get("alert_email","")
        pwd  = st.secrets.get("alert_email_password","")
        if not sndr or not pwd: return False,"Email credentials not set in Streamlit Secrets."
        msg = MIMEMultipart("alternative")
        msg["Subject"] = f"PEL ALERT — {machine} Risk {risk_pct:.0f}%"
        msg["From"]    = f"PEL AI System <{sndr}>"
        msg["To"]      = to
        html=f"""<html><body style="font-family:Inter,Arial;background:#f0f2f5;">
        <div style="max-width:560px;margin:0 auto;background:#fff;border-radius:12px;overflow:hidden;">
          <div style="background:#1a3a6b;padding:22px;text-align:center;">
            <img src="https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTFQ3PjNzDquakJIda7FDzsH32tqqD-_vomTQ&s"
                 width="55" style="border-radius:6px;">
            <h2 style="color:#fff;margin:10px 0 3px;font-size:17px;">PEL Maintenance Alert</h2>
            <p style="color:#a5c0e0;margin:0;font-size:12px;">Petroleum Exploration (Pvt.) Ltd.</p>
          </div>
          <div style="background:#dc2626;padding:12px;text-align:center;">
            <b style="color:#fff;font-size:14px;">🚨 Critical Risk Detected — {machine}</b>
          </div>
          <div style="padding:24px;">
            <table width="100%"><tr>
              <td style="background:#fef2f2;border-radius:8px;text-align:center;padding:14px;">
                <div style="font-size:28px;font-weight:700;color:#dc2626;">{risk_pct:.0f}%</div>
                <div style="font-size:10px;color:#6b7280;margin-top:3px;">FAILURE RISK</div>
              </td><td width="12"></td>
              <td style="background:#f9fafb;border-radius:8px;text-align:center;padding:14px;">
                <div style="font-size:22px;font-weight:700;color:#1a3a6b;">{vib:.2f}</div>
                <div style="font-size:10px;color:#6b7280;margin-top:3px;">VIBRATION mm/s</div>
              </td><td width="12"></td>
              <td style="background:#f9fafb;border-radius:8px;text-align:center;padding:14px;">
                <div style="font-size:22px;font-weight:700;color:#d97706;">{temp:.0f}°C</div>
                <div style="font-size:10px;color:#6b7280;margin-top:3px;">TEMPERATURE</div>
              </td>
            </tr></table>
            <div style="background:#fef2f2;border-left:4px solid #dc2626;border-radius:0 8px 8px 0;
                        padding:13px;margin-top:18px;">
              <p style="color:#7f1d1d;margin:0;font-size:13px;">
                Immediate inspection required for <b>{machine}</b> on Day #{day}.
                Risk threshold exceeded. Please schedule emergency maintenance.
              </p>
            </div>
            <p style="color:#6b7280;font-size:12px;margin-top:16px;">
              Generated: {datetime.now().strftime('%d %B %Y — %H:%M')} &nbsp;|&nbsp;
              PEL AI Predictive Maintenance v2.0
            </p>
          </div>
        </div></body></html>"""
        msg.attach(MIMEText(html,"html"))
        with smtplib.SMTP_SSL("smtp.gmail.com",465) as sv:
            sv.login(sndr,pwd); sv.sendmail(sndr,to,msg.as_string())
        return True,"✅ Alert email sent successfully!"
    except Exception as e:
        return False,str(e)

def should_send(r):
    if r<=CRIT: return False
    ls = st.session_state.get("last_alert")
    return ls is None or datetime.now()-ls>timedelta(minutes=60)

# ── CHART HELPER ────────────────────────────────────────────────
def chart_layout(fig, h=260):
    fig.update_layout(
        plot_bgcolor='#ffffff', paper_bgcolor='#ffffff',
        font_color='#374151', height=h,
        margin=dict(l=10,r=10,t=20,b=10),
        xaxis=dict(gridcolor='#f3f4f6'),
        yaxis=dict(gridcolor='#f3f4f6'),
        legend=dict(bgcolor='rgba(0,0,0,0)',orientation='h',yanchor='bottom',y=1.02)
    )
    return fig

