# ══ TAB 3 – FORECAST ════════════════════════════════════════════
with tabs[2]:
    fm = st.selectbox("Machine",MACHINES,key="fcm")
    df_fc = st.session_state.mdata[fm]
    lat_fc= df_fc.iloc[-1]
    rfc   = float(lat_fc['Predicted_Risk'])
    cd    = int(lat_fc['Day'])

    np.random.seed(cd%100)
    base=[min(rfc+i*0.012+np.random.uniform(-0.025,0.025),0.98) for i in range(30)]
    fd  =list(range(cd+1,cd+31))
    df_f=pd.DataFrame({'Day':fd,'Risk':base,
                       'Upper':[min(r+.07,1) for r in base],
                       'Lower':[max(r-.07,0) for r in base]})

    st.markdown("**30-Day Risk Forecast**")
    fig_f=go.Figure()
    fig_f.add_trace(go.Scatter(x=df_f['Day'],y=df_f['Upper'],
        fill=None,mode='lines',line_color='rgba(0,0,0,0)',showlegend=False))
    fig_f.add_trace(go.Scatter(x=df_f['Day'],y=df_f['Lower'],
        fill='tonexty',mode='lines',line_color='rgba(0,0,0,0)',
        fillcolor='rgba(26,58,107,0.08)',name='Confidence Interval'))
    fig_f.add_trace(go.Scatter(x=df_f['Day'],y=df_f['Risk'],
        mode='lines+markers',name='Forecast',
        line=dict(color='#1a3a6b',width=2.5),marker=dict(size=5)))
    fig_f.add_hline(y=CRIT,line_dash="dash",line_color="#dc2626",
                    annotation_text=f"Critical ({CRIT*100:.0f}%)")
    fig_f.add_hline(y=WARN,line_dash="dot",line_color="#d97706",
                    annotation_text=f"Warning ({WARN*100:.0f}%)")
    chart_layout(fig_f,340)
    fig_f.update_layout(yaxis=dict(range=[0,1.05],title="Predicted Risk"))
    st.plotly_chart(fig_f, use_container_width=True)

    # Heatmap
    st.markdown("**Risk Heatmap (Historical)**")
    hm=df_fc.tail(56).copy()
    hm['Week']=(hm.index//7).astype(int)
    hm['DOW'] =hm.index%7
    fig_hm=px.density_heatmap(hm,x='Week',y='DOW',z='Predicted_Risk',
                               color_continuous_scale='RdYlGn_r')
    fig_hm.update_layout(plot_bgcolor='#fff',paper_bgcolor='#fff',
                         font_color='#374151',height=220,margin=dict(l=10,r=10,t=20,b=10))
    st.plotly_chart(fig_hm, use_container_width=True)

    cr=[fd[i] for i,r in enumerate(base) if r>CRIT]
    wr=[fd[i] for i,r in enumerate(base) if WARN<r<=CRIT]
    fs1,fs2,fs3=st.columns(3)
    fs1.metric("Peak Risk",f"{max(base)*100:.1f}%",f"Day {fd[base.index(max(base))]}")
    fs2.metric("Critical Days",len(cr))
    fs3.metric("Warning Days",len(wr))
    if cr:
        st.markdown(f"<div class='acrit'>⚠️ First critical window in <b>{cr[0]-cd} days</b> (Day {cr[0]}). Schedule maintenance now.</div>",unsafe_allow_html=True)
    else:
        st.markdown("<div class='aok'>✅ No critical periods in next 30 days.</div>",unsafe_allow_html=True)

